#food-toggle.on{border-style:solid;border-color:rgba(212,175,55,.8);color:#e8d28b;box-shadow:0 0 22px rgba(212,175,55,.4);}
#trans-toggle{position:fixed;left:150px;top:385px;width:64px;height:64px;border-radius:50%;
  border:1.5px dashed rgba(0,212,255,.55);background:rgba(10,22,40,.55);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  box-shadow:0 0 18px rgba(0,212,255,.25),inset 0 0 12px rgba(0,212,255,.1);
  color:#bfe9ff;font-size:16px;letter-spacing:2px;cursor:pointer;z-index:1000;
  display:flex;align-items:center;justify-content:center;user-select:none;
  transition:border-color .2s,transform .2s,box-shadow .2s;}
#trans-toggle:hover{border-style:solid;border-color:rgba(0,212,255,.9);transform:scale(1.06);box-shadow:0 0 24px rgba(0,212,255,.45);}
#trans-toggle.on{border-style:solid;border-color:rgba(212,175,55,.8);color:#e8d28b;box-shadow:0 0 22px rgba(212,175,55,.4);}
#trans-overlay{position:fixed;inset:0;z-index:1400;display:none;padding:16px;background:rgba(5,12,24,.72);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);align-items:center;justify-content:center;}
#trans-overlay.open{display:flex;}
#trans-panel{position:relative;width:680px;max-width:94vw;max-height:86vh;overflow-y:auto;overscroll-behavior:contain;border:1px solid rgba(0,212,255,.35);border-radius:16px;padding:18px 20px 22px;background:linear-gradient(160deg,rgba(12,24,42,.96),rgba(8,16,30,.97));box-shadow:0 26px 70px rgba(0,0,0,.65),inset 0 0 40px rgba(0,212,255,.05);scrollbar-width:thin;scrollbar-color:rgba(0,212,255,.45) rgba(10,22,40,.4);}
#trans-panel::-webkit-scrollbar{width:6px;}
#trans-panel::-webkit-scrollbar-thumb{background:rgba(0,212,255,.45);border-radius:3px;}
.trans-toolbar{display:flex;gap:10px;margin-top:12px;flex-wrap:wrap;align-items:center;}
#trans-search{flex:1 1 180px;min-width:150px;padding:8px 12px;border-radius:10px;border:1px solid rgba(0,212,255,.3);background:rgba(10,22,40,.6);color:#e8eef7;font-size:12px;outline:none;transition:border-color .2s;}
#trans-search:focus{border-color:rgba(0,212,255,.8);box-shadow:0 0 0 2px rgba(0,212,255,.15);}
.trans-chips{display:flex;gap:6px;flex-wrap:wrap;}
.trans-chip{padding:4px 10px;font-size:11px;border:1px solid rgba(255,255,255,.15);border-radius:999px;background:transparent;color:#8a9bb0;cursor:pointer;transition:.2s;letter-spacing:1px;}
.trans-chip.active{border-color:rgba(212,175,55,.7);color:#e8d28b;background:rgba(212,175,55,.1);}
.trans-tabs{display:flex;gap:8px;margin:14px 0 12px;flex-wrap:wrap;}
.trans-tab{flex:1 1 auto;padding:9px 0;text-align:center;font-size:13px;letter-spacing:2px;border-radius:10px;border:1px solid rgba(0,212,255,.2);background:rgba(10,22,40,.4);color:#8a9bb0;cursor:pointer;transition:.2s;}
.trans-tab.active{color:#fff;background:rgba(0,212,255,.12);border-color:var(--tab-c,rgba(0,212,255,.7));box-shadow:0 0 12px rgba(0,212,255,.15);}
.trans-card{display:flex;gap:10px;padding:12px 12px 12px 0;margin-bottom:10px;border-radius:12px;border:1px solid rgba(0,212,255,.12);background:rgba(10,22,40,.5);overflow:hidden;transition:border-color .2s,transform .2s;}
.trans-card:hover{border-color:rgba(0,212,255,.35);transform:translateX(2px);}
.trans-color{flex:0 0 5px;border-radius:0 4px 4px 0;}
.trans-main{flex:1;min-width:0;padding-left:2px;}
.trans-name{font-size:14px;color:#eaf6ff;letter-spacing:1px;font-weight:600;}
.trans-route{font-size:12px;color:rgba(0,212,255,.8);font-weight:400;margin-left:6px;}
.trans-meta{font-size:11px;color:#a9bcd6;margin-top:4px;display:flex;gap:10px;flex-wrap:wrap;}
.trans-meta b{color:#8fd8ff;font-weight:600;}
.trans-note{font-size:12px;color:rgba(226,240,255,.65);line-height:1.6;margin-top:5px;}
.trans-actions{flex:0 0 auto;display:flex;flex-direction:column;gap:6px;justify-content:center;}
.trans-locate,.trans-expand{padding:6px 12px;font-size:11px;letter-spacing:1px;border-radius:9px;cursor:pointer;transition:.2s;background:transparent;}
.trans-locate{border:1px solid rgba(212,175,55,.45);color:#e8d28b;background:rgba(212,175,55,.06);}
.trans-locate:hover{background:rgba(212,175,55,.18);border-color:rgba(212,175,55,.8);color:#fff;}
.trans-expand{border:1px solid rgba(0,212,255,.35);color:#bfe9ff;background:rgba(0,212,255,.05);}
.trans-expand:hover{background:rgba(0,212,255,.15);border-color:rgba(0,212,255,.7);color:#fff;}
.trans-stops{display:none;margin-top:9px;padding-left:14px;position:relative;}
.trans-stops.open{display:block;}
.trans-stops::before{content:'';position:absolute;left:4px;top:8px;bottom:8px;width:2px;background:rgba(0,212,255,.22);border-radius:1px;}
.trans-stop{position:relative;padding:3px 0 3px 8px;font-size:12px;color:#c9d6e6;letter-spacing:.5px;}
.trans-stop::before{content:'';position:absolute;left:-13px;top:7px;width:8px;height:8px;border-radius:50%;background:#00d4ff;box-shadow:0 0 6px rgba(0,212,255,.7);}
.trans-stop:first-child::before,.trans-stop:last-child::before{background:#d4af37;box-shadow:0 0 6px rgba(212,175,55,.7);}
.trans-tips{margin-top:14px;padding-top:12px;border-top:1px solid rgba(212,175,55,.15);display:flex;flex-direction:column;gap:6px;font-size:12px;color:rgba(226,240,255,.7);line-height:1.65;}
.trans-tips b{color:#d4af37;font-weight:600;}
.trans-empty{text-align:center;color:#8a9bb0;font-size:13px;padding:30px 0;letter-spacing:1px;}

