var TRANS_CATS=[{id:'bus',name:'公交'},{id:'tour',name:'旅游专线'},{id:'train',name:'高铁动车'},{id:'ropeway',name:'索道游船'}];
var TRANS_AREA_CHIPS=['全部','古城','双廊','下关','喜洲','火车站','机场','才村','海东','丽江','昆明','香格里拉','苍山'];
var transCat='bus', transArea='全部', transKeyword='';
function transLineAreas(l){
  return [l.n,l.from,l.to].concat(l.stops).join(' ');
}
function transFiltered(){
  return TRANS_LINES.filter(function(l){
    if(l.cat!==transCat) return false;
    if(transArea!=='全部' && transLineAreas(l).indexOf(transArea)<0) return false;
    if(transKeyword && transLineAreas(l).indexOf(transKeyword)<0) return false;
    return true;
  });
}
function renderTransChips(){
  var box=document.getElementById('trans-chips');
  if(!box) return;
  box.innerHTML=TRANS_AREA_CHIPS.map(function(a){
    return '<button class="trans-chip'+(a===transArea?' active':'')+'" data-area="'+a+'">'+a+'</button>';
  }).join('');
  box.querySelectorAll('.trans-chip').forEach(function(el){
    el.addEventListener('click', function(){
      transArea=el.getAttribute('data-area');
      renderTransChips();
      renderTransList();
    });
  });
}
function renderTransTabs(){
  var box=document.getElementById('trans-tabs');
  if(!box) return;
  box.innerHTML=TRANS_CATS.map(function(c){
    var first=TRANS_LINES.filter(function(l){ return l.cat===c.id; })[0];
    return '<button class="trans-tab'+(c.id===transCat?' active':'')+'" data-cat="'+c.id+'"'+(first?' style="--tab-c:'+first.color+'"':'')+'>'+c.name+'</button>';
  }).join('');
  box.querySelectorAll('.trans-tab').forEach(function(el){
    el.addEventListener('click', function(){
      transCat=el.getAttribute('data-cat');
      renderTransTabs();
      renderTransList();
    });
  });
}
function renderTransList(){
  var box=document.getElementById('trans-list');
  if(!box) return;
  var list=transFiltered();
  if(!list.length){ box.innerHTML='<div class="trans-empty">没有找到匹配的线路，换个关键词试试</div>'; return; }
  var h='';
  list.forEach(function(l,i){
    h+='<div class="trans-card">'
      +'<div class="trans-color" style="background:'+l.color+'"></div>'
      +'<div class="trans-main">'
      +'<div class="trans-name">'+l.n+'<span class="trans-route">'+l.from+' ↔ '+l.to+'</span></div>'
      +'<div class="trans-meta"><span>首班 <b>'+l.first+'</b></span><span>末班 <b>'+l.last+'</b></span><span>票价 <b>'+l.price+'</b></span></div>'
      +'<div class="trans-note">'+l.note+'</div>'
      +'<div class="trans-stops" id="trans-stops-'+i+'">'+l.stops.map(function(s){ return '<div class="trans-stop">'+s+'</div>'; }).join('')+'</div>'
      +'</div>'
      +'<div class="trans-actions">'
      +'<button class="trans-locate" data-lng="'+l.ll[0]+'" data-lat="'+l.ll[1]+'" data-name="'+l.n+'">定位</button>'
      +'<button class="trans-expand" data-i="'+i+'">展开</button>'
      +'</div></div>';
  });
  box.innerHTML=h;
}
function openTransPanel(){
  renderTransChips();
  renderTransTabs();
  renderTransList();
  document.getElementById('trans-overlay').classList.add('open');
  document.getElementById('trans-toggle').classList.add('on');
}
function closeTransPanel(){
  document.getElementById('trans-overlay').classList.remove('open');
  document.getElementById('trans-toggle').classList.remove('on');
}
document.getElementById('trans-toggle').addEventListener('click', function(){
  if(document.getElementById('trans-overlay').classList.contains('open')) closeTransPanel(); else openTransPanel();
});
document.getElementById('trans-close').addEventListener('click', closeTransPanel);
document.getElementById('trans-overlay').addEventListener('click', function(e){
  if(e.target===this) closeTransPanel();
});
document.addEventListener('keydown', function(e){
  if(e.key==='Escape' && document.getElementById('trans-overlay').classList.contains('open')) closeTransPanel();
});
document.getElementById('trans-search').addEventListener('input', function(e){
  transKeyword=e.target.value.trim();
  renderTransList();
});
document.getElementById('trans-list').addEventListener('click', function(e){
  var loc=e.target.closest?e.target.closest('.trans-locate'):null;
  if(loc){
    var lng=parseFloat(loc.getAttribute('data-lng')), lat=parseFloat(loc.getAttribute('data-lat'));
    if(map){ map.flyTo([lat,lng],15,{duration:1.8,easeLinearity:.25}); showToast('已定位：'+loc.getAttribute('data-name')); }
    return;
  }
  var ex=e.target.closest?e.target.closest('.trans-expand'):null;
  if(ex){
    var st=document.getElementById('trans-stops-'+ex.getAttribute('data-i'));
    if(st){
      var open=st.classList.toggle('open');
      ex.textContent=open?'收起':'展开';
    }
  }
});
document.getElementById('food-toggle').addEventListener('click', function(){
